#include "RDPClipboardCore.h"
#include <winpr/sysinfo.h>
#include <winpr/clipboard.h>
#include <openssl/evp.h>
#include <stdlib.h>
#include <string.h>

BOOL mt_clip_validate(const BYTE* data,size_t length,size_t* meaningful){
 if(!data||length<2||length>MT_CLIP_WIRE_MAX||(length&1))return FALSE;
 size_t utf8=0;for(size_t pos=0;pos<length;pos+=2){UINT32 u=(UINT32)data[pos]|((UINT32)data[pos+1]<<8);
  if(!u){for(size_t tail=pos+2;tail<length;tail++)if(data[tail])return FALSE;if(meaningful)*meaningful=pos+2;return TRUE;}
  if(u>=0xD800&&u<=0xDBFF){if(pos+3>=length)return FALSE;UINT32 low=(UINT32)data[pos+2]|((UINT32)data[pos+3]<<8);if(low<0xDC00||low>0xDFFF)return FALSE;utf8+=4;pos+=2;}
  else if(u>=0xDC00&&u<=0xDFFF)return FALSE;
  else utf8+=u<0x80?1:u<0x800?2:3;
  if(utf8>MT_CLIP_UTF8_MAX)return FALSE;
 }return FALSE;
}
static void result(MTClipboard* clip,const char* type,UINT32 id,BOOL ok,const char* message,const BYTE* data,size_t length){
 cJSON* obj=cJSON_CreateObject();cJSON_AddStringToObject(obj,"type",type);cJSON_AddNumberToObject(obj,"id",id);cJSON_AddBoolToObject(obj,"ok",ok);
 if(message)cJSON_AddStringToObject(obj,"message",message);
 if(data){size_t capacity=4*((length+2)/3)+1;char* encoded=calloc(capacity,1);if(!encoded){cJSON_Delete(obj);return;}EVP_EncodeBlock((unsigned char*)encoded,data,(int)length);cJSON_AddStringToObject(obj,"data",encoded);memset(encoded,0,capacity);free(encoded);}
 clip->emit(clip->opaque,obj);
}
static void state(MTClipboard* clip){cJSON* obj=cJSON_CreateObject();cJSON_AddStringToObject(obj,"type","clipboardState");cJSON_AddBoolToObject(obj,"ready",clip->ready);cJSON_AddBoolToObject(obj,"remoteText",clip->remoteText);cJSON_AddBoolToObject(obj,"readBlocked",clip->readBlocked);cJSON_AddBoolToObject(obj,"offerBlocked",clip->offerBlocked);cJSON_AddNumberToObject(obj,"revision",(double)clip->revision);clip->emit(clip->opaque,obj);}
static void wipe_offer(MTClipboard* clip){if(clip->offered){memset(clip->offered,0,clip->offeredLength);free(clip->offered);}clip->offered=NULL;clip->offeredLength=0;}
static UINT capabilities(CliprdrClientContext* channel,const CLIPRDR_CAPABILITIES* caps){MTClipboard* clip=channel->custom;pthread_mutex_lock(&clip->lock);clip->caps=0;const BYTE* pointer=(const BYTE*)caps->capabilitySets;for(UINT32 i=0;pointer&&i<caps->cCapabilitiesSets;i++){const CLIPRDR_CAPABILITY_SET* set=(const CLIPRDR_CAPABILITY_SET*)pointer;if(set->capabilitySetLength<sizeof(*set))break;if(set->capabilitySetType==CB_CAPSTYPE_GENERAL&&set->capabilitySetLength>=CB_CAPSTYPE_GENERAL_LEN)clip->caps=((const CLIPRDR_GENERAL_CAPABILITY_SET*)set)->generalFlags&CB_USE_LONG_FORMAT_NAMES;pointer+=set->capabilitySetLength;}pthread_mutex_unlock(&clip->lock);return CHANNEL_RC_OK;}
static UINT monitor(CliprdrClientContext* channel,const CLIPRDR_MONITOR_READY* ready){(void)ready;MTClipboard* clip=channel->custom;pthread_mutex_lock(&clip->lock);CLIPRDR_GENERAL_CAPABILITY_SET general={.capabilitySetType=CB_CAPSTYPE_GENERAL,.capabilitySetLength=CB_CAPSTYPE_GENERAL_LEN,.version=CB_CAPS_VERSION_2,.generalFlags=clip->caps};CLIPRDR_CAPABILITIES caps={.cCapabilitiesSets=1,.capabilitySets=(CLIPRDR_CAPABILITY_SET*)&general};UINT status=channel->ClientCapabilities(channel,&caps);if(status==CHANNEL_RC_OK){clip->ready=TRUE;state(clip);}pthread_mutex_unlock(&clip->lock);return status;}
static UINT formats(CliprdrClientContext* channel,const CLIPRDR_FORMAT_LIST* list){MTClipboard* clip=channel->custom;pthread_mutex_lock(&clip->lock);clip->revision++;clip->remoteText=FALSE;wipe_offer(clip);if(clip->offerID)clip->offerStale=TRUE;
 if(list->numFormats<=1024)for(UINT32 i=0;i<list->numFormats;i++)if(list->formats[i].formatId==CF_UNICODETEXT)clip->remoteText=TRUE;
 CLIPRDR_FORMAT_LIST_RESPONSE response={.common.msgFlags=list->numFormats<=1024?CB_RESPONSE_OK:CB_RESPONSE_FAIL};UINT status=channel->ClientFormatListResponse(channel,&response);state(clip);pthread_mutex_unlock(&clip->lock);return status;
}
static UINT format_ack(CliprdrClientContext* channel,const CLIPRDR_FORMAT_LIST_RESPONSE* response){MTClipboard* clip=channel->custom;pthread_mutex_lock(&clip->lock);if(clip->offerID){BOOL ok=!clip->offerStale&&(response->common.msgFlags&CB_RESPONSE_OK)!=0&&(response->common.msgFlags&CB_RESPONSE_FAIL)==0;result(clip,"clipboardOfferResult",clip->offerID,ok,ok?NULL:clip->offerStale?"Remote clipboard changed before acknowledgement":"Server rejected clipboard text",NULL,0);clip->offerID=0;clip->offerStale=FALSE;if(!ok)wipe_offer(clip);}pthread_mutex_unlock(&clip->lock);return CHANNEL_RC_OK;}
static UINT data_request(CliprdrClientContext* channel,const CLIPRDR_FORMAT_DATA_REQUEST* request){MTClipboard* clip=channel->custom;pthread_mutex_lock(&clip->lock);BOOL allowed=!clip->readOnly&&clip->offered&&request->requestedFormatId==CF_UNICODETEXT;CLIPRDR_FORMAT_DATA_RESPONSE response={.common.msgFlags=allowed?CB_RESPONSE_OK:CB_RESPONSE_FAIL,.common.dataLen=allowed?(UINT32)clip->offeredLength:0,.requestedFormatData=allowed?clip->offered:NULL};UINT status=channel->ClientFormatDataResponse(channel,&response);pthread_mutex_unlock(&clip->lock);return status;}
static UINT data_response(CliprdrClientContext* channel,const CLIPRDR_FORMAT_DATA_RESPONSE* response){MTClipboard* clip=channel->custom;pthread_mutex_lock(&clip->lock);if(clip->readID){size_t length=0;BOOL ok=(response->common.msgFlags&CB_RESPONSE_OK)!=0&&(response->common.msgFlags&CB_RESPONSE_FAIL)==0&&clip->readRevision==clip->revision&&mt_clip_validate(response->requestedFormatData,response->common.dataLen,&length);result(clip,"clipboardReadResult",clip->readID,ok,ok?NULL:"Clipboard changed, unsupported Unicode or exceeds 1 MiB",ok?response->requestedFormatData:NULL,length);clip->readID=0;}pthread_mutex_unlock(&clip->lock);return CHANNEL_RC_OK;}
void mt_clip_init(MTClipboard* clip,void* opaque,void (*emit)(void*,cJSON*),BOOL readOnly){memset(clip,0,sizeof(*clip));pthread_mutex_init(&clip->lock,NULL);clip->opaque=opaque;clip->emit=emit;clip->readOnly=readOnly;}
void mt_clip_attach(MTClipboard* clip,CliprdrClientContext* channel){pthread_mutex_lock(&clip->lock);clip->channel=channel;channel->custom=clip;channel->ServerCapabilities=capabilities;channel->MonitorReady=monitor;channel->ServerFormatList=formats;channel->ServerFormatListResponse=format_ack;channel->ServerFormatDataRequest=data_request;channel->ServerFormatDataResponse=data_response;pthread_mutex_unlock(&clip->lock);}
void mt_clip_detach(MTClipboard* clip){pthread_mutex_lock(&clip->lock);clip->channel=NULL;clip->ready=FALSE;clip->remoteText=FALSE;clip->revision++;if(clip->readID)result(clip,"clipboardReadResult",clip->readID,FALSE,"Clipboard channel closed",NULL,0);if(clip->offerID)result(clip,"clipboardOfferResult",clip->offerID,FALSE,"Clipboard channel closed",NULL,0);clip->readID=0;clip->offerID=0;clip->readBlocked=FALSE;clip->offerBlocked=FALSE;wipe_offer(clip);state(clip);pthread_mutex_unlock(&clip->lock);}
void mt_clip_destroy(MTClipboard* clip){wipe_offer(clip);pthread_mutex_destroy(&clip->lock);}
void mt_clip_read(MTClipboard* clip,UINT32 id){pthread_mutex_lock(&clip->lock);if(!clip->ready||!clip->channel||!clip->remoteText||clip->readBlocked||clip->readID){result(clip,"clipboardReadResult",id,FALSE,"Copy Unicode text in the remote application first, or reconnect after a timeout",NULL,0);}else{clip->readID=id;clip->readRevision=clip->revision;clip->readDeadline=GetTickCount64()+10000;CLIPRDR_FORMAT_DATA_REQUEST request={.requestedFormatId=CF_UNICODETEXT};if(clip->channel->ClientFormatDataRequest(clip->channel,&request)!=CHANNEL_RC_OK){clip->readID=0;clip->readBlocked=TRUE;result(clip,"clipboardReadResult",id,FALSE,"Cannot request remote clipboard; reconnect to retry",NULL,0);state(clip);}}pthread_mutex_unlock(&clip->lock);}
static BYTE* decode(const char* encoded,size_t* length){if(!encoded)return NULL;size_t count=strlen(encoded);if(count<4||count>4*((MT_CLIP_WIRE_MAX+2)/3)||(count%4))return NULL;size_t padding=encoded[count-1]=='='?1:0;if(encoded[count-2]=='=')padding++;for(size_t i=0;i<count-padding;i++)if(!((encoded[i]>='A'&&encoded[i]<='Z')||(encoded[i]>='a'&&encoded[i]<='z')||(encoded[i]>='0'&&encoded[i]<='9')||encoded[i]=='+'||encoded[i]=='/'))return NULL;BYTE* bytes=malloc(count/4*3);if(!bytes)return NULL;int size=EVP_DecodeBlock(bytes,(const unsigned char*)encoded,(int)count);if(size<0||(size_t)size<padding){free(bytes);return NULL;}*length=(size_t)size-padding;return bytes;}
void mt_clip_offer(MTClipboard* clip,UINT32 id,const char* encoded){size_t bytes=0,length=0;BYTE* decoded=decode(encoded,&bytes);BOOL valid=mt_clip_validate(decoded,bytes,&length);pthread_mutex_lock(&clip->lock);if(!valid||clip->readOnly||!clip->ready||!clip->channel||clip->offerBlocked||clip->offerID){result(clip,"clipboardOfferResult",id,FALSE,"Clipboard unavailable, read-only, busy or invalid/oversized text",NULL,0);}else{wipe_offer(clip);clip->offered=decoded;decoded=NULL;clip->offeredLength=length;clip->offerID=id;clip->offerStale=FALSE;clip->offerDeadline=GetTickCount64()+10000;CLIPRDR_FORMAT format={.formatId=CF_UNICODETEXT,.formatName=NULL};CLIPRDR_FORMAT_LIST list={.numFormats=1,.formats=&format};if(clip->channel->ClientFormatList(clip->channel,&list)!=CHANNEL_RC_OK){clip->offerID=0;clip->offerBlocked=TRUE;wipe_offer(clip);result(clip,"clipboardOfferResult",id,FALSE,"Cannot announce clipboard text; reconnect to retry",NULL,0);state(clip);}}pthread_mutex_unlock(&clip->lock);if(decoded){memset(decoded,0,bytes);free(decoded);}}
void mt_clip_tick(MTClipboard* clip){pthread_mutex_lock(&clip->lock);UINT64 now=GetTickCount64();BOOL changed=FALSE;if(clip->readID&&now>=clip->readDeadline){result(clip,"clipboardReadResult",clip->readID,FALSE,"Clipboard read timed out; reconnect to retry",NULL,0);clip->readID=0;clip->readBlocked=TRUE;changed=TRUE;}if(clip->offerID&&now>=clip->offerDeadline){result(clip,"clipboardOfferResult",clip->offerID,FALSE,"Clipboard acknowledgement timed out; reconnect to retry",NULL,0);clip->offerID=0;clip->offerBlocked=TRUE;wipe_offer(clip);changed=TRUE;}if(changed)state(clip);pthread_mutex_unlock(&clip->lock);}
